import java.util.*;

class Solution {
    public int mySqrt(int x) {
        long lo = 0, hi = x, ans = 0;
        while (lo <= hi) {
            long mid = lo + (hi - lo) / 2;
            if (mid * mid <= x) {   // long math: no overflow
                ans = mid;          // mid is a valid root, look for a bigger one
                lo = mid + 1;
            } else {
                hi = mid - 1;       // mid is too big
            }
        }
        return (int) ans;
    }
}

